def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0: return False
    return True

def process_primes(num_list):
    primes = [x for x in num_list if is_prime(x)]
    if primes:
        return (min(primes), max(primes))
    return (None, None)
```

